def num(x):
    value=f'{float(x):.7g}'
    if 'e' in value:
        mantissa,exponent=value.split('e');return mantissa+r'\times10^{'+str(int(exponent))+'}'
    return value
def tidy(x):
    if isinstance(x,np.ndarray): return tidy(x.tolist())
    if isinstance(x,(list,tuple)): return [tidy(a) for a in x]
    if isinstance(x,dict): return {k:tidy(v) for k,v in x.items()}
    if isinstance(x,np.generic): return x.item()
    return x
def fill(s,v): return re.sub(r'@(\w+)@',lambda m: num(v[m[1]]) if isinstance(v[m[1]],(int,float,np.number)) else str(v[m[1]]),s).replace(r"\'", "'")
def part(label,prompt,marks,*steps): return (label,prompt,marks,steps)
def question(n,stem,refs,reason,v,parts,diagram=None):
    q={'number':n,'section':'','marks':sum(p[2] for p in parts),'stem':fill(stem,v),
       'syllabusRefs':refs,'cognitiveDemand':reason,
       'parts':[{'label':a,'prompt':fill(b,v),'marks':c} for a,b,c,d in parts],
       'markScheme':[{'part':a,'steps':[{'code':code,'text':fill(text,v)} for code,text in d]} for a,b,c,d in parts]}
    for p,g in zip(q['parts'],q['markScheme']):
        assert sum(int(re.search(r'\d+',s['code'])[0]) for s in g['steps'])==p['marks'],(n,p['label'])
    q['answerSummary']='; '.join(g['steps'][-1]['text'] for g in q['markScheme'])
    if diagram:q['diagramSvg']=diagram
    RECORDS.append({'set':CURRENT,'question':n,'syllabusRefs':refs,'parts':[{'label':p[0],'marks':p[2]} for p in parts],
                    'computedEvidence':tidy(v),'reviewFocus':reason,
                    'partChecks':[{'part':p['label'],'marks':p['marks'],'status':'passed',
                                   'evidenceKind':'author worked derivation and additive mark check; fresh independent numerical evidence is in the separate review',
                                   'workedReasoning':[s['text'] for s in g['steps']],
                                   'markCodeSum':sum(int(re.search(r'\d+',s['code'])[0]) for s in g['steps'])}
                                  for p,g in zip(q['parts'],q['markScheme'])]})
    return q
def plot(xlim,ylim,series=(),points=(),xlabel='x',ylabel='y',xticks=(),yticks=(),title=''):
    width,height=640,350; L,R,T,B=70,30,40,60
    fw,fh=width-L-R,height-T-B
    if 'km' in xlabel and 'km' in ylabel:
        unit=min(fw/(xlim[1]-xlim[0]),fh/(ylim[1]-ylim[0]));dw=(xlim[1]-xlim[0])*unit;dh=(ylim[1]-ylim[0])*unit
        L+=(fw-dw)/2;T+=(fh-dh)/2;fw,fh=dw,dh
    bottom=T+fh;right=L+fw
    def xy(x,y):return (L+(x-xlim[0])/(xlim[1]-xlim[0])*fw,bottom-(y-ylim[0])/(ylim[1]-ylim[0])*fh)
    s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" width="640" height="350"><rect width="640" height="350" fill="white"/><g font-family="Arial" font-size="15" fill="#111">']
    for x in xticks:
        a,b=xy(x,ylim[0]);s.append(f'<path d="M {a:.2f} {T} V {bottom}" stroke="#ddd"/><text x="{a:.2f}" y="{bottom+24}" text-anchor="middle">{x}</text>')
    for y in yticks:
        a,b=xy(xlim[0],y);s.append(f'<path d="M {L} {b:.2f} H {right}" stroke="#ddd"/><text x="{L-12}" y="{b+5:.2f}" text-anchor="end">{y}</text>')
    s.append(f'<path d="M {L} {T} V {bottom} H {right}" fill="none" stroke="black" stroke-width="1.6"/>')
    for data,color,dash in series:
        path=' '.join(('M' if i==0 else 'L')+f'{xy(x,y)[0]:.2f},{xy(x,y)[1]:.2f}' for i,(x,y) in enumerate(data))
        s.append(f'<path d="{path}" fill="none" stroke="{color}" stroke-width="2.2" stroke-dasharray="{dash}"/>')
    for x,y,label in points:
        a,b=xy(x,y);s.append(f'<circle cx="{a:.2f}" cy="{b:.2f}" r="4"/><text x="{a+8:.2f}" y="{b-10:.2f}">{label}</text>')
    ylab=max(18,L-48)
    s.append(f'<text x="{width/2}" y="{height-12}" text-anchor="middle">{xlabel}</text><text x="{ylab}" y="{height/2}" transform="rotate(-90 {ylab} {height/2})" text-anchor="middle">{ylabel}</text><text x="{width/2}" y="22" text-anchor="middle">{title}</text></g></svg>')
    return ''.join(s)
def graph(nodes,edges):
    s=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 350" width="640" height="350"><rect width="640" height="350" fill="white"/><g font-family="Arial" font-size="16">']
    for a,b,w in edges:
        x,y=nodes[a];u,v=nodes[b];s.append(f'<path d="M{x},{y} L{u},{v}" stroke="#555" stroke-width="1.6"/>')
        mx,my=(x+u)/2,(y+v)/2
        s.append(f'<rect x="{mx-11}" y="{my-17}" width="24" height="22" fill="white"/><text x="{mx}" y="{my}" text-anchor="middle">{w}</text>')
    for a,(x,y) in nodes.items():s.append(f'<circle cx="{x}" cy="{y}" r="18" fill="white" stroke="black" stroke-width="1.8"/><text x="{x}" y="{y+6}" text-anchor="middle">{a}</text>')
    return ''.join(s)+ '</g></svg>'
def distances(vertices,edges):
    d={a:{b:0 if a==b else math.inf for b in vertices} for a in vertices}
    for a,b,w in edges:d[a][b]=d[b][a]=w
    for k in vertices:
        for a in vertices:
            for b in vertices:d[a][b]=min(d[a][b],d[a][k]+d[k][b])
    return d
def mst(vertices,edges):
    parent={a:a for a in vertices}
    def root(a):
        while parent[a]!=a:a=parent[a]
        return a
    selected=[]
    for a,b,w in sorted(edges,key=lambda e:e[2]):
        u,v=root(a),root(b)
        if u!=v:parent[u]=v;selected.append((a,b,w))
    assert len(selected)==len(vertices)-1
    return sum(e[2] for e in selected),selected
def table(head,rows):return '\n\n| '+' | '.join(map(str,head))+' |\n| '+' | '.join(['---']*len(head))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in rows)+'\n\n'
def paper(set_,qs):
    assert len(qs)==6 and sum(q['marks'] for q in qs)==110,(set_,[(q['number'],q['marks']) for q in qs])
    p={'id':f'ai-hl-set-{set_.lower()}-paper-2','strand':'ai','course':'hl','set':set_,'paper':'2',
       'title':f'Mathematics AI HL - Set {set_} - Paper 2','minutes':120,'marks':110,'calculator':True,'questions':qs}
    data=(json.dumps(p,ensure_ascii=False,indent=2)+'\n').encode();file=OUT/(p['id']+'.json');file.write_bytes(data)
    return {'id':p['id'],'sha256':hashlib.sha256(data).hexdigest(),'questions':6,'marks':110}

